[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>GreenBean Coffee — Your Daily Coffee Ritual</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --green: #00824A;
      --green-dark: #32462F;
      --cream: #F3CEA1;
      --cream-light: #FDF6EC;
      --brown: #6B3A2A;
      --text: #1E1E1E;
      --text-muted: #5C5C5C;
      --white: #FFFFFF;
      --radius: 16px;
    }
    html { scroll-behavior: smooth; }
    body { font-family: 'DM Sans', sans-serif; color: var(--text); background: var(--white); }
    h1,h2,h3 { font-family: 'DM Serif Display', serif; }
    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; display: block; }

    /* ── NAV ── */
    .nav {
      position: sticky; top: 0; z-index: 100;
      background: var(--white);
      border-bottom: 1px solid #e8e8e8;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 32px; height: 64px;
    }
    .nav-logo { display: flex; align-items: center; gap: 10px; }
    .nav-logo svg { width: 40px; height: 40px; }
    .nav-logo-text { font-family: 'DM Serif Display', serif; font-size: 1.25rem; color: var(--green-dark); }
    .nav-links { display: flex; gap: 8px; }
    .nav-links a {
      padding: 8px 14px; border-radius: 999px; font-size: .9rem; font-weight: 500;
      color: var(--text); transition: background .2s;
    }
    .nav-links a:hover { background: #f0f0f0; }
    .nav-actions { display: flex; gap: 10px; align-items: center; }
    .btn { display: inline-flex; align-items: center; justify-content: center; border-radius: 999px; font-family: 'DM Sans', sans-serif; font-weight: 600; cursor: pointer; transition: all .2s; border: none; }
    .btn-outline { padding: 8px 20px; border: 2px solid var(--green-dark); color: var(--green-dark); background: transparent; font-size: .9rem; }
    .btn-outline:hover { background: var(--green-dark); color: var(--white); }
    .btn-green { padding: 10px 24px; background: var(--green); color: var(--white); font-size: .95rem; }
    .btn-green:hover { background: #006b3c; }
    .btn-green-dark { padding: 10px 24px; background: var(--green-dark); color: var(--white); font-size: .95rem; }
    .btn-green-dark:hover { background: #243520; }
    .btn-cream { padding: 10px 24px; background: var(--cream); color: var(--green-dark); font-size: .95rem; }
    .btn-cream:hover { background: #eabf8e; }
    .nav-hamburger { display: none; flex-direction: column; gap: 5px; cursor: pointer; }
    .nav-hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; }

    /* ── COOKIE BANNER ── */
    #cookie-banner {
      position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
      background: var(--green-dark); color: var(--white);
      padding: 20px 32px; display: flex; align-items: center; justify-content: space-between; gap: 24px;
      box-shadow: 0 -4px 24px rgba(0,0,0,.15);
    }
    #cookie-banner p { font-size: .9rem; max-width: 640px; line-height: 1.5; }
    #cookie-banner p strong { display: block; margin-bottom: 4px; font-size: 1rem; }
    .cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }
    .btn-cookie-settings { padding: 8px 18px; border-radius: 999px; border: 2px solid rgba(255,255,255,.5); color: var(--white); background: transparent; font-family: 'DM Sans', sans-serif; font-weight: 600; font-size: .875rem; cursor: pointer; transition: all .2s; }
    .btn-cookie-settings:hover { border-color: var(--white); }
    .btn-cookie-agree { padding: 8px 20px; border-radius: 999px; background: var(--cream); color: var(--green-dark); border: none; font-family: 'DM Sans', sans-serif; font-weight: 700; font-size: .875rem; cursor: pointer; transition: all .2s; }
    .btn-cookie-agree:hover { background: #eabf8e; }

    /* ── HERO ── */
    .hero {
      min-height: 540px; display: flex; align-items: center;
      background: linear-gradient(135deg, var(--green-dark) 0%, #1a3018 100%);
      position: relative; overflow: hidden; padding: 80px 60px;
    }
    .hero::before {
      content: ''; position: absolute; top: -80px; right: -80px;
      width: 500px; height: 500px; border-radius: 50%;
      background: radial-gradient(circle, rgba(243,206,161,.15) 0%, transparent 70%);
    }
    .hero::after {
      content: ''; position: absolute; bottom: -100px; left: 30%;
      width: 400px; height: 400px; border-radius: 50%;
      background: radial-gradient(circle, rgba(0,130,74,.2) 0%, transparent 70%);
    }
    .hero-content { max-width: 560px; z-index: 1; }
    .hero-eyebrow { font-size: .85rem; font-weight: 600; color: var(--cream); letter-spacing: .08em; text-transform: uppercase; margin-bottom: 16px; }
    .hero h1 { font-size: clamp(2.5rem, 5vw, 4rem); color: var(--white); line-height: 1.1; margin-bottom: 28px; }
    .hero-visual {
      position: absolute; right: 60px; top: 50%; transform: translateY(-50%);
      width: 360px; height: 360px; border-radius: 50%;
      background: linear-gradient(145deg, var(--cream) 0%, #e8b87a 100%);
      display: flex; align-items: center; justify-content: center;
      box-shadow: 0 24px 80px rgba(0,0,0,.4);
      z-index: 1;
    }
    .hero-visual-inner { text-align: center; }
    .hero-cup { font-size: 5rem; }
    .hero-tagline { font-size: .9rem; color: var(--green-dark); font-weight: 600; margin-top: 8px; }

    /* ── PROMO CARD ── */
    .section { padding: 72px 60px; }
    .section-narrow { padding: 72px 60px; max-width: 1200px; margin: 0 auto; }
    .promo-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; max-width: 1200px; margin: 0 auto; }
    .promo-card {
      border-radius: var(--radius); overflow: hidden; position: relative;
      min-height: 380px; display: flex; flex-direction: column; justify-content: flex-end;
      padding: 36px;
    }
    .promo-card-citrus { background: linear-gradient(160deg, #d4f5d0 0%, #a8e6c8 40%, #00824A 100%); }
    .promo-card-afternoon { background: linear-gradient(160deg, #2c1810 0%, #8B3A2A 50%, #D4844A 100%); }
    .promo-card-ai { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); }
    .promo-card-nondairy { background: linear-gradient(160deg, #f9f3e8 0%, #F3CEA1 60%, #e8b87a 100%); }
    .promo-icon { font-size: 3.5rem; margin-bottom: 20px; }
    .promo-card h2 { font-size: clamp(1.4rem, 2.5vw, 1.9rem); margin-bottom: 12px; line-height: 1.2; }
    .promo-card-citrus h2, .promo-card-nondairy h2 { color: var(--green-dark); }
    .promo-card-afternoon h2, .promo-card-ai h2 { color: var(--white); }
    .promo-card p { font-size: .95rem; line-height: 1.6; margin-bottom: 24px; }
    .promo-card-citrus p, .promo-card-nondairy p { color: var(--green-dark); }
    .promo-card-afternoon p, .promo-card-ai p { color: rgba(255,255,255,.85); }
    .promo-deco {
      position: absolute; top: 24px; right: 24px;
      width: 120px; height: 120px; border-radius: 50%;
      background: rgba(255,255,255,.12);
    }
    .promo-deco2 {
      position: absolute; top: -20px; right: 60px;
      width: 80px; height: 80px; border-radius: 50%;
      background: rgba(255,255,255,.08);
    }

    /* ── FULL WIDTH PROMO ── */
    .full-promo {
      display: grid; grid-template-columns: 1fr 1fr;
      min-height: 480px; max-width: 1200px; margin: 0 auto 28px; border-radius: var(--radius); overflow: hidden;
    }
    .full-promo-content { padding: 60px; display: flex; flex-direction: column; justify-content: center; }
    .full-promo-content h2 { font-size: clamp(1.8rem, 3vw, 2.5rem); margin-bottom: 16px; line-height: 1.2; }
    .full-promo-content p { font-size: 1rem; line-height: 1.65; margin-bottom: 28px; color: var(--text-muted); }
    .full-promo-visual { position: relative; overflow: hidden; }
    .full-promo-visual-inner {
      position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
      font-size: 7rem;
    }
    .promo-fruity { background: linear-gradient(135deg, #fff8f0 0%, #fde8cc 100%); }
    .promo-fruity .full-promo-visual { background: linear-gradient(135deg, #ff8c42 0%, #ffb347 40%, #ffd280 100%); }
    .promo-spring { background: linear-gradient(135deg, #f0f8f5 0%, #d0edd8 100%); }
    .promo-spring .full-promo-visual { background: linear-gradient(135deg, #a8d5ba 0%, #7ec8a0 40%, #00824A 100%); }

    /* ── SECTION HEADING ── */
    .section-heading { text-align: center; margin-bottom: 48px; }
    .section-heading h2 { font-size: clamp(1.8rem, 3vw, 2.6rem); color: var(--green-dark); margin-bottom: 12px; }
    .section-heading p { font-size: 1rem; color: var(--text-muted); max-width: 520px; margin: 0 auto; line-height: 1.6; }

    /* ── FOOTER ── */
    footer { background: var(--green-dark); color: var(--white); padding: 64px 60px 32px; }
    .footer-top { display: grid; grid-template-columns: repeat(5, 1fr); gap: 40px; margin-bottom: 48px; }
    .footer-col h4 { font-family: 'DM Sans', sans-serif; font-size: .85rem; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--cream); margin-bottom: 16px; }
    .footer-col ul { list-style: none; }
    .footer-col ul li { margin-bottom: 10px; }
    .footer-col ul li a { font-size: .875rem; color: rgba(255,255,255,.75); transition: color .2s; }
    .footer-col ul li a:hover { color: var(--white); }
    .footer-bottom { border-top: 1px solid rgba(255,255,255,.1); padding-top: 28px; display: flex; align-items: center; justify-content: space-between; }
    .footer-social { display: flex; gap: 16px; }
    .footer-social a { width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,.1); display: flex; align-items: center; justify-content: center; font-size: 1rem; transition: background .2s; }
    .footer-social a:hover { background: rgba(255,255,255,.2); }
    .footer-copy { font-size: .8rem; color: rgba(255,255,255,.5); }

    /* mobile footer accordion */
    .footer-acc-toggle { display: none; }
    .footer-acc-body { }

    /* ── RESPONSIVE ── */
    @media (max-width: 900px) {
      .nav-links { display: none; }
      .nav-hamburger { display: flex; }
      .nav-links.open { display: flex; flex-direction: column; position: absolute; top: 64px; left: 0; right: 0; background: var(--white); padding: 16px 24px; border-bottom: 1px solid #eee; gap: 4px; }
      .hero { padding: 60px 24px; min-height: auto; }
      .hero-visual { display: none; }
      .section { padding: 48px 24px; }
      .promo-grid { grid-template-columns: 1fr; }
      .full-promo { grid-template-columns: 1fr; }
      .full-promo-visual { min-height: 240px; }
      .footer-top { grid-template-columns: 1fr; gap: 0; }
      .footer-col { border-bottom: 1px solid rgba(255,255,255,.1); }
      .footer-acc-toggle {
        display: flex; align-items: center; justify-content: space-between;
        width: 100%; background: none; border: none; color: var(--cream);
        font-family: 'DM Sans', sans-serif; font-size: .85rem; font-weight: 700;
        letter-spacing: .06em; text-transform: uppercase; padding: 18px 0; cursor: pointer;
      }
      .footer-acc-toggle .acc-arrow { transition: transform .3s; font-style: normal; }
      .footer-acc-toggle.open .acc-arrow { transform: rotate(180deg); }
      .footer-acc-body { display: none; padding-bottom: 16px; }
      .footer-acc-body.open { display: block; }
      footer { padding: 40px 24px 24px; }
      .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
      #cookie-banner { flex-direction: column; padding: 20px 24px; }
      .cookie-actions { width: 100%; }
    }
    @media (max-width: 600px) {
      .nav { padding: 0 20px; }
      .nav-actions .btn-outline { display: none; }
    }
  </style>
</head>
<body>

<!-- COOKIE BANNER -->
<div id="cookie-banner" role="alert" aria-live="polite">
  <p>
    <strong>This site uses cookies, but not the kind you eat</strong>
    We use cookies to remember log in details, provide secure log in, improve site functionality, and deliver personalized content.
  </p>
  <div class="cookie-actions">
    <button class="btn-cookie-settings" onclick="document.getElementById('cookie-banner').style.display='none'">Change cookie settings</button>
    <button class="btn-cookie-agree" onclick="document.getElementById('cookie-banner').style.display='none'">Agree</button>
  </div>
</div>

<!-- NAV -->
<nav class="nav">
  <a href="index.html" class="nav-logo" aria-label="GreenBean Coffee Home">
