    <button class="nav-hamburger" id="hamburger" aria-label="Toggle navigation" aria-expanded="false">
      <span></span><span></span><span></span>
    </button>
  </div>
</nav>

<!-- HERO -->
<section class="hero" aria-label="Hero">
  <div class="hero-content">
    <p class="hero-eyebrow">Spring 2026</p>
    <h1>It's a great day for coffee</h1>
    <a href="menu.html" class="btn btn-green" style="font-size:1rem;padding:14px 32px;">Start an order</a>
  </div>
  <div class="hero-visual" aria-hidden="true">
    <div class="hero-visual-inner">
      <div class="hero-cup">☕</div>
      <p class="hero-tagline">Handcrafted with love</p>
    </div>
  </div>
</section>

<!-- FEATURED + AFTERNOON (2-col grid) -->
<div class="section">
  <div class="promo-grid">
    <!-- Citrus Energy -->
    <div class="promo-card promo-card-citrus" role="region" aria-label="Featured Product">
      <div class="promo-deco" aria-hidden="true"></div>
      <div class="promo-deco2" aria-hidden="true"></div>
      <div class="promo-icon" aria-hidden="true">🍋</div>
      <h2>New Citrus Energy Refreshers just dropped</h2>
      <p>Introducing a new kind of energy. Now you can enjoy the Refreshers you love with extra caffeine from nature and a B-vitamin boost.</p>
      <a href="menu.html" class="btn btn-green-dark" style="align-self:flex-start;">Give them a try</a>
    </div>
    <!-- Afternoon Reset -->
    <div class="promo-card promo-card-afternoon" role="region" aria-label="Afternoon Promotion">
      <div class="promo-deco" aria-hidden="true"></div>
      <div class="promo-icon" aria-hidden="true">🌤️</div>
      <h2>Your afternoon reset</h2>
      <p>When 2 p.m. hits and you need a little boost, we've got you covered — with tasty drinks, snacks and sweet treats to keep the good vibes going.</p>
      <a href="menu.html" class="btn btn-cream" style="align-self:flex-start;">Explore our afternoon menu</a>
    </div>
    <!-- AI Recommendation -->
    <div class="promo-card promo-card-ai" role="region" aria-label="AI Recommendation">
      <div class="promo-deco" aria-hidden="true"></div>
      <div class="promo-icon" aria-hidden="true">✨</div>
      <h2>Inspire your next order with ChatGPT</h2>
      <p>Discover drinks that fit your mood, goals and preferences in just a few conversational prompts.</p>
      <a href="#" class="btn btn-cream" style="align-self:flex-start;">Learn more</a>
    </div>
    <!-- Nondairy -->
    <div class="promo-card promo-card-nondairy" role="region" aria-label="Nondairy Promotion">
      <div class="promo-deco" aria-hidden="true"></div>
      <div class="promo-icon" aria-hidden="true">🌿</div>
      <h2>Nondairy, No extra</h2>
      <p>Enjoy your beverage with your choice of nondairy milk — like oat, almond, coconut or soy — for no additional charge.</p>
      <a href="menu.html" class="btn btn-green" style="align-self:flex-start;">Start an order</a>
    </div>
  </div>
</div>

<!-- SEASONAL HIGHLIGHTS -->
<div class="section" style="padding-top:0;">
  <!-- Fruity twist -->
  <div class="full-promo promo-fruity" role="region" aria-label="Fruity Seasonal Highlight">
    <div class="full-promo-content">
      <p class="hero-eyebrow" style="color:var(--brown);">New arrival</p>
      <h2 style="color:var(--brown);">A new fruity twist is here</h2>
      <p>Introducing vibrant Iced Mango Cream Matcha and rich Iced Mango Cream Chai. Topped with velvety mango cream cold foam for a delicious pop of sweetness, sip after sip.</p>
      <a href="menu.html" class="btn btn-green-dark" style="align-self:flex-start;font-size:.95rem;">Order now</a>
    </div>
    <div class="full-promo-visual">
      <div class="full-promo-visual-inner" aria-hidden="true">🥭</div>
    </div>
  </div>
  <!-- Spring starts now -->
  <div class="full-promo promo-spring" role="region" aria-label="Spring Seasonal Highlight">
    <div class="full-promo-visual" style="order:-1;">
      <div class="full-promo-visual-inner" aria-hidden="true">🌸</div>
    </div>
    <div class="full-promo-content">
      <p class="hero-eyebrow" style="color:var(--green);">Spring menu</p>
      <h2 style="color:var(--green-dark);">Spring starts now</h2>
      <p>Iced Lavender Cream Matcha and Iced Lavender Cream Chai are back in bloom, joined by the new Iced Ube Coconut Macchiato, Toasted Coconut Cream Cold Brew and so much more.</p>
      <a href="menu.html" class="btn btn-green" style="align-self:flex-start;font-size:.95rem;">See the spring menu</a>
    </div>
  </div>
</div>

<!-- FOOTER -->
<footer>
  <div class="footer-top">
    <!-- About Us -->
    <div class="footer-col">
      <button class="footer-acc-toggle" aria-expanded="false">About Us <em class="acc-arrow">▾</em></button>
