  function shiftCarousel(id, dir) {
    if (!carouselOffsets[id]) carouselOffsets[id] = 0;
    const track = document.getElementById(id + '-track');
    const count = track.children.length;
    const visible = getVisible(id);
    const maxOffset = Math.max(0, count - visible);
    carouselOffsets[id] = Math.min(Math.max(carouselOffsets[id] + dir, 0), maxOffset);
    const pct = carouselOffsets[id] * (100 / visible);
    track.style.transform = `translateX(-${pct}%)`;
    // Update button states
    const prevBtn = track.closest('.carousel-wrapper').querySelector('.carousel-btn-prev');
    const nextBtn = track.closest('.carousel-wrapper').querySelector('.carousel-btn-next');
    if (prevBtn) prevBtn.disabled = carouselOffsets[id] === 0;
