    .filter-chip { padding: 7px 16px; border-radius: 999px; border: 2px solid var(--border); background: var(--white); font-family: 'DM Sans', sans-serif; font-size: .85rem; font-weight: 600; cursor: pointer; color: var(--text); transition: all .2s; }
    .filter-chip:hover { border-color: var(--green); color: var(--green); }
