    .btn-filter-clear { padding: 8px 20px; background: var(--white); color: var(--text-muted); border: 2px solid var(--border); border-radius: 999px; font-family: 'DM Sans', sans-serif; font-size: .875rem; font-weight: 600; cursor: pointer; transition: all .2s; }
