    .map-pin:hover .map-pin-label, .map-pin.active .map-pin-label { opacity: 1; }
    .map-pin.active .map-pin-icon svg circle { fill: var(--green-dark); }

    /* POPUP */
    .map-popup { position: absolute; background: var(--white); border-radius: 14px; padding: 16px 20px; box-shadow: 0 8px 32px rgba(0,0,0,.18); z-index: 20; width: 220px; display: none; }
