    .map-popup-close { position: absolute; top: 8px; right: 10px; background: none; border: none; font-size: 1rem; cursor: pointer; color: var(--text-muted); }

    /* FOOTER */
    footer { background: var(--green-dark); color: var(--white); padding: 48px 60px 28px; }
    .footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px; margin-bottom: 36px; }
