  // Nav hamburger
  const hamburger = document.getElementById('hamburger');
  const navLinks = document.getElementById('nav-links');
  hamburger.addEventListener('click', () => {
    const open = navLinks.classList.toggle('open');
    hamburger.setAttribute('aria-expanded', open);
  });

  // Order type toggle
  function setOrderType(type) {
    document.getElementById('btn-pickup').classList.toggle('active', type === 'pickup');
    document.getElementById('btn-delivery').classList.toggle('active', type === 'delivery');
    document.getElementById('btn-pickup').setAttribute('aria-pressed', type === 'pickup');
    document.getElementById('btn-delivery').setAttribute('aria-pressed', type === 'delivery');
    // Simulate results update
    const count = type === 'delivery' ? 5 : 8;
    document.getElementById('result-count').textContent = count;
  }

  // Search input with suggestions
  const searchInput = document.getElementById('location-search');
  const suggestions = document.getElementById('search-suggestions');
  searchInput.addEventListener('input', () => {
    suggestions.classList.toggle('visible', searchInput.value.length > 1);
  });
  searchInput.addEventListener('blur', () => {
    setTimeout(() => suggestions.classList.remove('visible'), 150);
  });
  searchInput.addEventListener('focus', () => {
    if (searchInput.value.length > 1) suggestions.classList.add('visible');
  });
  function selectSuggestion(val) {
    searchInput.value = val;
    suggestions.classList.remove('visible');
    document.getElementById('result-location').textContent = val;
    performSearch();
  }
  function performSearch() {
    if (searchInput.value) {
      document.getElementById('result-location').textContent = searchInput.value;
    }
  }

  // Filter panel
  function toggleFilter() {
    const panel = document.getElementById('filter-panel');
    const btn = document.getElementById('filter-btn');
    const open = panel.classList.toggle('open');
    btn.classList.toggle('active', open);
    btn.setAttribute('aria-expanded', open);
  }
  function toggleChip(chip) {
    const active = chip.classList.toggle('active');
    chip.setAttribute('aria-pressed', active);
  }
  function applyFilters() {
    toggleFilter();
  }
  function clearFilters() {
    document.querySelectorAll('.filter-chip.active').forEach(c => {
      c.classList.remove('active');
      c.setAttribute('aria-pressed', 'false');
    });
  }

  // Store / pin selection
  const storeData = [
    { name: 'Pike Place Market', addr: '1912 Pike Pl, Seattle, WA 98101', pinPos: { left: '42%', top: '38%' } },
    { name: 'Capitol Hill', addr: '253 Broadway E, Seattle, WA 98102', pinPos: { left: '55%', top: '28%' } },
