    { name: 'Westlake Center', addr: '400 Pine St, Seattle, WA 98101', pinPos: { left: '44%', top: '35%' } },
    { name: 'Fremont', addr: '3624 Fremont Ave N, Seattle, WA 98103', pinPos: { left: '35%', top: '18%' } },
    { name: 'University District', addr: '4201 University Way NE, Seattle, WA 98105', pinPos: { left: '60%', top: '15%' } },
    { name: 'Ballard', addr: '5430 Ballard Ave NW, Seattle, WA 98107', pinPos: { left: '28%', top: '13%' } },
