  ];

  const pins = document.querySelectorAll('.map-pin');
  const cards = document.querySelectorAll('.store-card');
  const popup = document.getElementById('map-popup');

  function selectStore(idx) {
    // Update cards
    cards.forEach((c, i) => c.classList.toggle('selected', i === idx));
    // Update pins
    pins.forEach((p, i) => p.classList.toggle('active', i === idx));
    // Scroll card into view
    cards[idx].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    // Show popup
    document.getElementById('popup-name').textContent = storeData[idx].name;
    document.getElementById('popup-addr').textContent = storeData[idx].addr;
    const store = storeData[idx];
    popup.style.left = `calc(${store.pinPos.left} + 20px)`;
    popup.style.top = store.pinPos.top;
    popup.classList.add('visible');
  }
  function closePopup() {
    popup.classList.remove('visible');
  }
</script>
